begin;
select set_config('request.jwt.claim.sub','3d935a76-c6fe-44b6-b248-fcbe58c6bf1c',true);
select set_config('request.jwt.claims','{"sub":"3d935a76-c6fe-44b6-b248-fcbe58c6bf1c","role":"authenticated"}',true);
select set_config('test.support_ticket',gen_random_uuid()::text,true);
set local role authenticated;
do $$ declare x jsonb;begin
 x:=public.crm_support_action_v1('access');if x->>'approver'<>'false' then raise exception 'employee approver';end if;
 x:=public.crm_support_action_v1('create',current_setting('test.support_ticket')::uuid,'{"section":"Задачи","description":"Проверка тестом, откатывается","blocking":true}');
 if not exists(select 1 from public.crm_support_tickets_v1 where id=current_setting('test.support_ticket')::uuid) then raise exception 'own unreadable';end if;
 begin perform public.crm_support_action_v1('approve',current_setting('test.support_ticket')::uuid,'{}');raise exception 'employee approved';exception when insufficient_privilege then null;end;
 begin update public.crm_support_tickets_v1 set status='closed' where id=current_setting('test.support_ticket')::uuid;raise exception 'direct mutation';exception when insufficient_privilege then null;end;
end $$;
reset role;
select public.crm_support_save_analysis_v1(current_setting('test.support_ticket')::uuid,1,'{"summary":"Проверка","proposal":"Исправить тестовый сбой","verification":"Проверить маршрут","questions":""}');
select set_config('test.support_plan',(select id::text from public.crm_support_plans_v1 where ticket_id=current_setting('test.support_ticket')::uuid),true);
select set_config('request.jwt.claim.sub','19dd9943-99ae-47c4-a39c-4f82a11059a6',true);
set local role authenticated;
do $$ begin if exists(select 1 from public.crm_support_tickets_v1 where id=current_setting('test.support_ticket')::uuid) then raise exception 'other employee read';end if;begin perform public.crm_support_action_v1('comment',current_setting('test.support_ticket')::uuid,'{"body":"чужое"}');raise exception 'other employee wrote';exception when insufficient_privilege then null;end;end $$;
reset role;
select set_config('request.jwt.claim.sub','bcc330b8-9100-4c60-b87f-22a36988fc97',true);
set local role authenticated;
do $$ begin if exists(select 1 from public.crm_support_tickets_v1) then raise exception 'blocked read';end if;begin perform public.crm_support_action_v1('access');raise exception 'blocked allowed';exception when insufficient_privilege then null;end;begin perform public.crm_support_action_v1('create',null,'{"section":"x","description":"blocked"}');raise exception 'blocked create';exception when insufficient_privilege then null;end;end $$;
reset role;
select set_config('request.jwt.claim.sub','3d935a76-c6fe-44b6-b248-fcbe58c6bf1c',true);
set local role authenticated;
select public.crm_support_action_v1('comment',current_setting('test.support_ticket')::uuid,'{"body":"Уточнение после анализа"}');
reset role;
select set_config('request.jwt.claim.sub','544fb1e2-ef70-44de-bc62-e0e1596a4bfc',true);
set local role authenticated;
do $$ begin begin perform public.crm_support_action_v1('approve',current_setting('test.support_ticket')::uuid,jsonb_build_object('plan_id',current_setting('test.support_plan')));raise exception 'stale approval';exception when others then if sqlerrm<>'SUPPORT_PLAN_CHANGED' then raise;end if;end;end $$;
reset role;
select public.crm_support_save_analysis_v1(current_setting('test.support_ticket')::uuid,2,'{"summary":"Проверка","proposal":"Новый согласуемый план","verification":"Проверить все роли","questions":""}');
select set_config('test.support_plan',(select id::text from public.crm_support_plans_v1 where ticket_id=current_setting('test.support_ticket')::uuid and revision=2),true);
set local role authenticated;
select public.crm_support_action_v1('approve',current_setting('test.support_ticket')::uuid,jsonb_build_object('plan_id',current_setting('test.support_plan')));
select public.crm_support_action_v1('resolve',current_setting('test.support_ticket')::uuid,'{"body":"Исправлено в тесте, проверены маршрут и все роли; это откатываемый тест."}');
reset role;
select set_config('request.jwt.claim.sub','3d935a76-c6fe-44b6-b248-fcbe58c6bf1c',true);
set local role authenticated;
select public.crm_support_action_v1('confirm',current_setting('test.support_ticket')::uuid);
select public.crm_support_action_v1('reopen',current_setting('test.support_ticket')::uuid,'{"body":"Проблема повторилась, нужен новый разбор"}');
do $$ begin if not exists(select 1 from public.crm_support_tickets_v1 where id=current_setting('test.support_ticket')::uuid and status='review' and revision=3) then raise exception 'reopen failed';end if;if (select count(*) from public.crm_support_events_v1 where ticket_id=current_setting('test.support_ticket')::uuid)<7 then raise exception 'history lost';end if;end $$;
reset role;
rollback;
